INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u20605@imasmallorca.net', 'MARGARITA CREMADES OLIVER', 'UFAG Residència Llar dels Ancians', 'Direcció de la Residència Llar dels Ancians', 'Contracte simplificat abreujat (art. 159.6) per la prestació del servei de socorrista de piscina a la Residència Llar dels Ancians', 'Prestar el servei d''un socorrista de piscina durant el mesos de juliol i agost dels anys 2026, 2027, 2028 i 2029
A) Dur a terme les pròpies del socorrista, (vigilància i primers auxilis), d''acord amb la normativa legal vigent.
B) Vigilar que els usuaris respectin les normes d''ús de la instal·lació i informar-los de les mateixes, en cas que n''actuïn de forma contrària. El socorrista té el deure de fer complir la normativa de règim intern sempre que estigui especificada i a la vista dels usuaris.
C) Omplir el llibre d''incidències amb les actuacions que hagi dut a terme.
D) Col·laborar amb els plans d''emergència i evacuació de la instal·lació en cas de que sigui necessari.
E) Col·laborar, si són requerits en tots els actes de dinamització social i jornades de recreació que s''organitzin a la piscina.
F) Atenció a l''usuari, orientació, trasllat de persones disminuïdes, ajuda a persones amb mobilitat reduïda, etc...
G) Controlar l''ordre i l''aforament màxim establert per normativa, dins el recinte de la piscina.
H) Fer complir la distribució dels espais, entre els usuaris, així com el control del material esportiu que s''utilitza, així com mantenir l''ordre dins del recinte de la piscina.
I) El socorrista no podrà abandonar mai la instal·lació i sempre haurà d''estar a punt per a actuar en qualsevol incident.', 'A) Coordinador del servei localitzable les 24 hores.
B) Titulació vigent i actualitzada en socorrisme aquàtic i Tècnic en SVB (Suport Vital Bàsic) i ús del DEA (Desfibril·lador Extern Automàtic) de tot el personal adscrit al servei.
C) El contractista està obligat a demanar al personal que efectivament desenvolupi el servei la certificació negativa de delictes de naturalesa sexual, i a entregar aquesta a la Direcció del Centre abans de l''inici de la prestació del servei, o cada vegada que es produeixi un canvi de personal.
D) Substitució immediata del personal en cas de necessitat.
E) Assegurança de Responsabilitat Civil.
F) Alta a la Seguretat Social de la totalitat de la jornada de tot el personal adscrit al servei.

Horaris:
Any 2026:
- Del dia 1 de juliol al 31 d''agost de dilluns a dissabte de 9:30 a 13:00 hores i de 16:00 a 19:00 hores ? 53 dies x 6,5 hores = 344,5 hores.
Any 2027:
- Del dia 1 de juliol al 31 d''agost de dilluns a dissabte de 9:30 a 13:00 hores i de 16:00 a 19:00 hores ? 53 dies x 6,5 hores = 344,5 hores.
Any 2028:
En cas de dur-se a terme la pròrroga contractual els dies i hores de prestació del servei seran comunicats per l''IMAS, sense que variïn substancialment del número d''hores establertes per a l''any 2026 i 2027.
Any 2029:
En cas de dur-se a terme la pròrroga contractual els dies i hores de prestació del servei seran comunicats per l''IMAS, sense que variïn substancialment del número d''hores establertes per a l''any 2026 i 2027.', 'Servei', 'prestació de caràcter recurrent el valor estimat de la qual no supera els 15.000,00  en un termini màxim de 5 anualitats', 53, '79714000', '10', '23110', '22609', 12396.69, 2603.3, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/_layouts/15/Doc.aspx?sourcedoc=%7BA67E52D5-BCC8-43F3-9926-A0588052D9D1%7D&file=Plec%20de%20Prescripcions%20T%C3%A8cniques%20SOCORRISTA(1)_MARGARITA%20CREMADES%20O.docx&action=default&mobileredirect=true"]', 'El pressupost és estimat per un any. Es tracta d''un contracte obert simplicat plurianual amb publicitat per una durada mínima de 2 anys i amb possibles pròrrogues de dos anys més.', 'AD', '1445015Q', NULL, NULL, NULL, 0, 0, NULL);
