INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Huialfàs', 'Direcció de la Residència Huialfàs', 'Davant el mal estat de les rajoles dels banys masculí i femení de la planta número 1, esdevé URGENT i NECESSARI substituir les actual rajoles, fer un nou sol i juntes especials per evitar el que ha succeït: l''orina a espanyat les juntes i provocar humitats a la planta inferior.
Per tant, se presta el servei d''empresa especialitzada de construcció per substituir l''enrajolat del bany de la primera planta d''accés general per residents i visitant a mes de la substitució canaleta aigües pluvials.', 'Enrajolat del bany de la planta 1 i substitució de les canals d''aigües pluvials per rompudes.', 'Nou enrajolat antilliscant i substitució canaleta aigües pluvials', 'Obra', 'despesa puntual', 365, '0', '10', '23119', '', 1826.44, 383.55, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/Ppto.%20Socies_Obres%20bany%20+%20canals_MARIA%20ISABEL%20MAYOL%20M.pdf"]', NULL, 'CF', NULL, NULL, NULL, NULL, 0, 0, NULL);
INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Huialfàs', 'Direcció de la Residència Huialfàs', 'L''adquisició d''aquests productes respon a la necessitat de mantenir i millorar els espais verds i les àrees comunes de la residència, garantint un entorn agradable, segur i acollidor per als residents, familiars i personal.', 'Sustrat per al jardí: És indispensable per al correcte manteniment i renovació de les zones enjardinades, assegurant la salut de les plantes i contribuint a l''estètica de l''entorn exterior.
Brides per fermar brancals: Es requereixen per assegurar l''estabilitat i la correcta subjecció d''elements vegetals i estructures, evitant riscos de caiguda i garantint la seguretat als espais exteriors.
Poinseties per a decoració interior: Aquestes plantes ornamentals s''incorporen per crear un ambient càlid i festiu, especialment en èpoques assenyalades, afavorint el benestar emocional dels residents i millorant la imatge institucional de la residència.', 'SUSTRAT PER JARDI RESIDÈNCIA
BRIDES PER FERMAR BRANCAL
PONSETIAS DECORACIÓ INTERIOR', 'Subministrament', 'despesa puntual', 365, '3110000', '10', '23113', '22107', 100.0, 21.03, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/02.01.26%20-%20N%C2%BA%20AL.%20000010%20-%20TORRANDELL%20-%20CAS%20S_MARIA%20ISABEL%20MAYOL%20M.pdf", "https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/02.01.26%20-%20N%C2%BA%20AL.%20000009%20-%20TORRANDELL%20-%20CAS%20S_MARIA%20ISABEL%20MAYOL%20M.pdf"]', 'Ja s''ha realitzat l''adquisició d''aquests bens.', 'OFI', '1411565H', NULL, NULL, NULL, 0, 0, NULL);
