INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Huialfàs', 'Direcció de la Residència Huialfàs', 'La columna de pre-neteja ha presentat una ruptura estructural que impedeix el seu funcionament normal. Aquest element és necessari per al pre-rentat de vaixella i estris abans de la seva introducció al rentavaixelles industrial, així com la substitució de l''aixeta. Ha estat una avaria urgent de la qual no s''ha pogut sol·licitat pressuposts anticipadament, ja que es una despesa necessaria per al correcte funcionament de la cuina.', 'Reparació urgent de la columna de pre-neteja del rentaplats de la cuina de la Residència.', 'COLUMNA PRELAVADO MM1/2 GENEBRE
