INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Huialfàs', 'Direcció de la Residència Huialfàs', 'Es necessari la prestació externa del servei de fisioteràpia a la residència per actuar amb els residents a nivell preventiu, rehabilitador o manteniment de la salut. Aquest servei es troba externalitzat fins a la contractació d''un profesional a la RLLT de la Residència Huialfas.', 'Servei de fisioterapia per als residents del centre', 'Les sessions es duran a terme durant 3 dies a la setmana entre les 9:30 a 13:30 hores (12 hores setmanals durant tot l''any)', 'Servei', 'prestació de caràcter recurrent el valor estimat de la qual no supera els 15.000,00  en un termini màxim de 5 anualitats', 31, '85142100', '10', '23113', '22709', 1267.34, 266.14, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/ANNEX%20II%20Oferta%20economica_MARIA%20ISABEL%20MAYOL%20M.pdf"]', 'El contracte amb OXIGEN va finalitzar el 31/08/2025, però l''empresa segueix prestant els serveis en les mateixes condicions', 'OFI', '1441729C', NULL, NULL, NULL, 0, 0, NULL);
INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Huialfàs', 'Direcció de la Residència Huialfàs', 'Es necessita el manteniment i revisió de l''ascensor perquè els treballadors i treballadores es desplacin amb els carros per la residència i realitzar les cures pertinents als usuaris. A més, també els empren els usuaris per a poder desplaçar-se lliurament per a la residència.', 'Manteniment ascensor del centre', 'Es realitzen 4 revisions i manteniment a l''any.', 'Servei', 'prestació de caràcter recurrent el valor estimat de la qual no supera els 15.000,00  en un termini màxim de 5 anualitats', 93, '50750000', '10', '23119', '21300', 310.38, 65.18, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/contrato%20residencia%20huialfas_MARIA%20ISABEL%20MAYOL%20M.pdf"]', 'Es prorroga automaticament cada 01 de gener', 'OFI', '1441729C', NULL, NULL, NULL, 0, 0, NULL);
