compresor', 'Servei', 'despesa puntual', 365, '50881000', '10', '23119', '21300', 445.4, 93.53, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/Pressupost_Res.%20Huialfas_Mallorklima%20(reparac_MARIA%20ISABEL%20MAYOL%20M.pdf"]', NULL, 'ADO', '1444098R', NULL, NULL, NULL, 0, 0, NULL);
