INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Huialfàs', 'Direcció de la Residència Huialfàs', 'Es necessari actualitzar el Pla d''Autoprotecció de la Residència Huialfàs per garantir la seguretat de residents, professionals i visitants.', 'Servei d''actualització del Pla d''Autoprotecció de la Residència Huialfas.', 'Els honoraris inlouen les següents actuacions:

o  Anexo de deficiencias en caso de que existieran.
o Presentación de un borrador previo para ser corregido por el Departamento de prevención.
o Visitas de obra y reuniones previas necesarias con la propiedad.
o Asesoramiento técnico.
o Gastos de copistería del Plan de Autoprotección (1 copia) y un CD para la Dirección
General de Emergencias.
o Tramitación ante la Dirección General de Emergencias.
o Tasas de visado del Colegio de Ingenieros.
o Tasas de las Consejerías Competentes en la materia', 'Servei', 'despesa puntual', 365, '71317000', '10', '23113', '22706', 2750.0, 577.5, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/OF_26_001%20ACTUALITZACI%C3%93%20EMERG%20AUTOPROT.%20HUIAL_MARIA%20ISABEL%20MAYOL%20M.pdf"]', 'Sol·licitud creació partida 10.23113.22706', 'ADO', '1444102Y', NULL, NULL, NULL, 0, 0, NULL);
