INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Miquel Mir', 'Direcció de la Residència Miquel Mir', 'Els dos ascensors de les plantes de la Residència no estan adaptats als residents amb deteriorament cognitiu, sent un perill per a la seva integritat física, atès que poden cridar l''ascensor i ficar-se dedins sense que el personal de planta d''adoni (la residència té molts de punt sense una bona visibilitat per par de les TCAI).
