INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Miquel Mir', 'Direcció de la Residència Miquel Mir', 'La Residència Miquel Mir necessita subministrar aigua potable per als residents i treballadors del centre', 'Servei de subministrament de garrafes d''aigua potable', '11 Botellas de 18.9 litres
12 Packs envassos', 'Subministrament', 'prestació de caràcter recurrent el valor estimat de la qual no supera els 15.000,00  en un termini màxim de 5 anualitats', 31, '41110000', '10', '23116', '22105', 200.0, 42.0, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/TRES%20GLOPS_05.01.26_MARIA%20ISABEL%20MAYOL%20M.pdf"]', 'La comanda esta feta, ja que per al 2026 es preveu la contractació amb aquesta empresa a l''expedient 973512A.', 'OFI', '1441729C', 'F/2026/1033', NULL, NULL, 0, 0, NULL);
INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Miquel Mir', 'Direcció de la Residència Miquel Mir', 'Per tal de realitzar diversos tallers i activitats amb els residents es necessita material per fer manualitats i treballar la psicomotricitat dels usuaris.', 'Subministrament material pedagògic per a treballar amb els residents', 'Pintures (ceres, llapisos de colors, rotuladors, tèmperes, pintura de dits...) paper de diferents textures ( cartolines, de seda, celofan, crespon...) aros i pilotes, plastilina etc', 'Subministrament', 'despesa puntual', 365, '39162100', '10', '23116', '22000', 942.44, 197.91, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/Presupuesto%20material%20did%C3%A1ctico%20AL05087400%20De_MARIA%20ISABEL%20MAYOL%20M.pdf"]', NULL, 'ADO', '1444145H', NULL, NULL, NULL, 0, 0, NULL);
INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Miquel Mir', 'Direcció de la Residència Miquel Mir', 'S''ha detectat un embús al depòsit d''aigües residuals i greixos procedents de la cuina i  s''ha de buidar de manera urgent, per evitar que l''aigua segueixi vessant i provoqui desperfectes a les bombes que han d''impulsar dites aigües a les canonades del carrer.
També ha passat el mateix amb el depòsit d''aigües fecals de la residència.
És necessari que els depòsits puguin emmagatzemar les corresponents aigües residuals, tant les de la cuina com les de la residència. Per aquest motiu i de forma urgent s''ha hagut de contractar una empresa especialitzada en buidatge del depòsits.', 'Desembossar els dipòsists d''aigües fecals i de greixos de la cuina.', 'Desembossar els dipòsists d''aigües fecals i de greixos de la cuina.', 'Servei', 'despesa puntual', 120, '90640000', '10', '23119', '21200', 250.0, 52.5, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/Pressupost%20Limpiezas%20Industriales%20Colis%20(buid_MARIA%20ISABEL%20MAYOL%20M.pdf"]', NULL, 'ADO', '1444150P', 'F/2026/1497', NULL, NULL, 0, 0, NULL);
