INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u26974@imasmallorca.net', 'MARIA ISABEL MAYOL MARCH', 'UFAG Residència Miquel Mir', 'Direcció de la Residència Miquel Mir', 'La Residència Miquel Mir compta amb un sistema de distribució de gasos medicinals (oxígen i buit). S''ha detectat que encara que no s''empri l''oxigen, aquest es va gastant. Per aquest motiu, és necessari que vengui l''empresa que fa el manteniment del sistema de gasos medicinals, cerqui i repara la fugida de l''oxigen.
Segons el tècnic per poder trobar la fuga, s''ha de sectoritzar la instal·lació ja que només hi ha una clau de tall a la planta 1. Per aquest motiu, es necessari instal·lar varies claus de pas per poder localitzar-la.', 'Instal·lació de 3 a 5 claus de tall a la planta 1 per sectoritzar el sistema de distribució de gasos medicinals', 'Treball de sectorització del sistema de distribució de gasos medicinals', 'Servei', 'despesa puntual', 365, '50421000', '10', '23119', '21200', 1820.0, 382.2, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/Pressupost_Res.%20Miquel%20Mir_Carburos%20Medica%20-_MARIA%20ISABEL%20MAYOL%20M.pdf"]', NULL, 'OFI', '1441729C', NULL, NULL, NULL, 0, 0, NULL);
