INSERT INTO peticions (hora, email, nom, organ_contractacio, responsable_contracte, justificacio, objecte_contracte, caracteristiques_tecniques, tipus_contracte, tipus_despesa, termini_execucio, codi_cpv, partida_organica, partida_programa, partida_economica, base_imposable, quota_iva, fitxers_pressupost, detalls_addicionals, sistema_tramitacio, segex, reg_factura, relacio_q, relacio_o, finalitzat, publicat, created_by) VALUES ('2026-01-01T00:00:00.000Z', 'u27949@imasmallorca.net', 'JUAN DE VILLALONGA CALAFAT', 'UFAG Residència Son Caulelles', 'Direcció de la Residència Son Caulelles', 'Servicio de Transporte (Excursión a Inca)', 'Servicio de Transporte usuarios (Excursión a Inca)', 'El presente informe tiene como objeto sol·licitar un servicio de transporte especializado para nuestro centro, Residencia Son Caulelles. Este servicio es fundamental para garantizar la movilidad y el bienestar de nuestros residentes, facilitando su acceso a destinos recreativos, como playas, parques, centros culturales y otros lugares de interés. Este servicio es crucial para alcanzan varios objetivos significativos relacionados con el bienestar físico, emocional y social de nuestros residentes. 
Se realizará la salida el día 22/01/2026 desde la Residencia Son Caluelles a la fábrica 
Quely en Inca.

- Vehículo adaptado y equipado para el acceso de silla de ruedas. 
- Sistemas de sujeción y anclaje para garantizar la seguridad de los pasajeros durante 
el traslado. 
- Capacidad mínima para 7 sillas de ruedas.', 'Servei', 'prestació de caràcter recurrent el valor estimat de la qual no supera els 15.000,00  en un termini màxim de 5 anualitats', 120, '60100000', '10', '23118', '22300', 492.91, 49.29, '["https://imasmallorca.sharepoint.com/sites/IMAIMP-UGEResidencial/Documentos%20compartidos/Aplicaciones/Microsoft%20Forms/COMUNICACI%C3%93%20DE%20NECESSITATS%20DE%20L%E2%80%99%20%C3%93RGAN%20DE%20CONTRACT/Pressupost%20sol%C2%B7licitat%20a%20prove%C3%AFdor/Presupuesto%2018-22012025%20(1)_JUAN%20DE%20VILLALONGA%20C.pdf"]', 'Excursión a Inca (OFI) Solicitud realizada por el departamento de trabajadores sociales.', 'OFI', '1411565H', 'F/2026/702', NULL, NULL, 0, 0, NULL);
